<?php
declare(strict_types=1);
namespace App\Application\Review\AI;
use App\Domain\Review\Enum\NotebookAnalysisActionType;
final class NotebookAnalysisResponseValidator { /** @return list<array{type:string,concept_id:?string,question_id:?string,reason:string,confidence:float,front?:string,back?:string,flashcard_id?:string}> */ public function validate(array $payload):array {if(!array_key_exists('actions',$payload)||!is_array($payload['actions'])||count($payload['actions'])>20)throw new \InvalidArgumentException('Resposta de análise inválida.');$actions=[];foreach($payload['actions'] as $action){if(!is_array($action)||!is_string($action['type']??null)||!is_string($action['reason']??null)||!is_numeric($action['confidence']??null))throw new \InvalidArgumentException('Ação de análise inválida.');$type=NotebookAnalysisActionType::tryFrom($action['type']);$confidence=(float)$action['confidence'];if($type===null||$confidence<0||$confidence>1||mb_strlen(trim($action['reason']))<3||mb_strlen($action['reason'])>500)throw new \InvalidArgumentException('Ação de análise fora do schema.');$item=['type'=>$type->value,'concept_id'=>is_string($action['concept_id']??null)?$action['concept_id']:null,'question_id'=>is_string($action['question_id']??null)?$action['question_id']:null,'reason'=>trim($action['reason']),'confidence'=>$confidence];if($type===NotebookAnalysisActionType::CREATE_OR_REUSE_CARD){if(!is_string($action['front']??null)||!is_string($action['back']??null)||trim($action['front'])===''||trim($action['back'])==='')throw new \InvalidArgumentException('Card sem conteúdo válido.');$item['front']=trim($action['front']);$item['back']=trim($action['back']);}if($type===NotebookAnalysisActionType::ADVANCE_CARD){if(!is_string($action['flashcard_id']??null))throw new \InvalidArgumentException('Card a antecipar inválido.');$item['flashcard_id']=$action['flashcard_id'];}$actions[]=$item;}return $actions;} public function jsonSchema():array{return ['type'=>'object','additionalProperties'=>false,'required'=>['actions'],'properties'=>['actions'=>['type'=>'array','maxItems'=>20]]];} }
